begin;
select no_plan();
insert into auth.users(id,email) select ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,'group-'||i::text||'@example.test' from generate_series(4101,4108) i;
insert into public.profiles(id,name,age,sex,height_cm,weight_kg,units,experience,equipment,days_per_week,session_minutes,goal)
select id,'Group '||right(id::text,4),30,'female',165,65,'metric','beginner',array['none'],3,30,'maintain' from auth.users where email like 'group-41%@example.test';
insert into public.goals(app_id,user_id,goal_type,effective_date,weekly_workout_target) select 'group-goal-'||id::text,id,'maintain','2026-09-01',3 from public.profiles where name like 'Group 41%';
insert into public.daily_targets(app_id,user_id,goal_row_id,version,effective_date,calories,protein_g,carbs_g,fat_g,bmr,bmi,tdee,activity_factor,formula,disclaimer)
select 'group-target-'||user_id::text,user_id,row_id,1,'2026-09-01',2200,120,240,65,1400,23.9,2200,1.5,'test','Estimates only' from public.goals where app_id like 'group-goal-%';
create temp table group_test_state(name text primary key,value jsonb);
grant all on group_test_state to authenticated,service_role;
select ok(not has_table_privilege('authenticated','private.cooking_invitations','select'),'PIN hashes not exposed');
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004101';
insert into group_test_state values('invite',public.cooking_group_command('{"action":"invite","idempotencyKey":"group-invite-one"}'));
select matches((select value->>'pin' from group_test_state where name='invite'),'^[A-Z0-9]{6}$','six-character PIN');
select is(jsonb_array_length(public.get_cooking_group_week('2026-10-18')->'group'->'members'),1,'group starts with one member');
select ok(not has_table_privilege('authenticated','public.cooking_groups','insert'),'no direct group writes');
select ok(not has_function_privilege('authenticated','public.get_group_planning_context(uuid,jsonb)','execute'),'private planning facts are service-only');
select ok(not has_function_privilege('anon','public.get_cooking_group_week(date)','execute'),'anonymous denied');
select throws_ok($$select public.cooking_group_command('{"action":"leave","groupId":"00000000-0000-0000-0000-000000000001","groupRevision":1,"idempotencyKey":"foreign-leave"}')$$,'P0001',null,'cannot leave a foreign group');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004102';
insert into group_test_state values('review',public.cooking_group_command(jsonb_build_object('action','inspect-pin','pin',(select value->>'pin' from group_test_state where name='invite'))));
select is((select value->>'inviter' from group_test_state where name='review'),'Group 4101','review exposes display name');
select is(public.get_cooking_group_week('2026-10-18')->'group','null'::jsonb,'inspection does not join');
insert into group_test_state values('joined',public.cooking_group_command(jsonb_build_object('action','join','pin',(select value->>'pin' from group_test_state where name='invite'),'groupRevision',1,'idempotencyKey','group-join-two')));
select is(jsonb_array_length(public.get_cooking_group_week('2026-10-18')->'group'->'members'),2,'two accounts connected');
select is(public.cooking_group_command(jsonb_build_object('action','join','pin',(select value->>'pin' from group_test_state where name='invite'),'groupRevision',1,'idempotencyKey','group-join-two'))->>'success','true','duplicate join retries replay');
select is((select count(*) from public.profiles),1::bigint,'other profile remains private');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004103';
select ok(public.cooking_group_command(jsonb_build_object('action','inspect-pin','pin',(select value->>'pin' from group_test_state where name='invite'))) ? 'error','PIN consumed once');
select is((select count(*) from public.cooking_group_members),0::bigint,'outsider cannot read membership');
set local role service_role;
set local "request.jwt.claim.role"='service_role';
insert into group_test_state values('input',jsonb_build_object('reviewPolicyVersion','advisory_v1','groupId',(select value->'group'->>'id' from group_test_state where name='invite'),'weekOf','2026-10-18','memberIds',jsonb_build_array('00000000-0000-0000-0000-000000004101','00000000-0000-0000-0000-000000004102'),'selectedDates',jsonb_build_array('2026-10-18'),'mode','fill','recipes','[]'::jsonb,'seed','test','overrides','{}'::jsonb));
select lives_ok($$insert into group_test_state values('context',public.get_group_planning_context('00000000-0000-0000-0000-000000004101',(select value from group_test_state where name='input')))$$,'service obtains planning basis');
select ok(jsonb_array_length((select value->'recipes' from group_test_state where name='context'))>0,'shared recipes available to planner');
select throws_ok($$select public.get_group_planning_context('00000000-0000-0000-0000-000000004103',(select value from group_test_state where name='input'))$$,'P0001',null,'service helper rejects unrelated actor');
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004101';
select lives_ok($$select public.mutate_cooking_group_week(jsonb_build_object('reviewPolicyVersion','advisory_v1','groupId',(select value->'group'->>'id' from group_test_state where name='invite'),'weekOf','2026-10-18','revision',0,'action','grocery','operation','amount','amount',120550,'idempotencyKey','shared-amount'))$$,'amount-only week saves');
select is((public.get_cooking_group_week('2026-10-18')->'grocery'->>'totalAmountCentavos')::numeric,120550::numeric,'shared amount is recorded');
select throws_ok($$select public.mutate_cooking_group_week(jsonb_build_object('reviewPolicyVersion','advisory_v1','groupId',(select value->'group'->>'id' from group_test_state where name='invite'),'weekOf','2026-10-18','revision',0,'action','grocery','operation','amount','amount',10,'idempotencyKey','stale-amount'))$$,'P0001',null,'stale list revision rejected');
select is((select count(*) from public.grocery_lists),0::bigint,'personal lists untouched');
set local role service_role;
set local "request.jwt.claim.role"='service_role';
update group_test_state set value=jsonb_set(value,'{recipes}',jsonb_build_array(jsonb_build_object('id','meal-korean-beef-bowl','revision',(select revision from public.meals where app_id='meal-korean-beef-bowl'),'maxBatches',2))) where name='input';
insert into group_test_state values('fresh-context',public.get_group_planning_context('00000000-0000-0000-0000-000000004101',(select value from group_test_state where name='input')));
insert into group_test_state values('preview',public.store_group_planning_preview('00000000-0000-0000-0000-000000004101',(select value from group_test_state where name='input'),jsonb_build_object('basis',(select value->>'basis' from group_test_state where name='fresh-context'),'warnings','[]'::jsonb,'replacements','[]'::jsonb,'batches',jsonb_build_array(jsonb_build_object('recipeId','meal-korean-beef-bowl','name','Korean Beef Bowl','yield',4,'portions',3,'batches',1,'leftovers',1)),
'assignments',jsonb_build_array(jsonb_build_object('id','gp-test-a','memberId','00000000-0000-0000-0000-000000004101','recipeId','meal-korean-beef-bowl','date','2026-10-18','slot','lunch','servings',1.5),jsonb_build_object('id','gp-test-b','memberId','00000000-0000-0000-0000-000000004102','recipeId','meal-korean-beef-bowl','date','2026-10-18','slot','lunch','servings',1.5)))));
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
select lives_ok($$select public.commit_cooking_group_plan(jsonb_build_object('previewId',(select value->>'id' from group_test_state where name='preview'),'acknowledged',true,'idempotencyKey','group-commit'))$$,'group generation commits atomically');
select is(public.commit_cooking_group_plan(jsonb_build_object('previewId',(select value->>'id' from group_test_state where name='preview'),'acknowledged',true,'idempotencyKey','group-commit'))->>'success','true','unchanged commit retry replays');
select is(jsonb_array_length(public.get_cooking_group_week('2026-10-18')->'assignments'),2,'one authoritative assignment per member');
select is((select count(*) from public.planned_meals),1::bigint,'only own plan assignment directly readable');
select is((select count(*) from public.nutrition_logs),0::bigint,'generation never logs intake');
select is((public.get_cooking_group_week('2026-10-18')->'grocery'->>'totalAmountCentavos')::numeric,120550::numeric,'generation preserves shared spending');
select ok(jsonb_array_length(public.get_cooking_group_week('2026-10-18')->'grocery'->'items')>0,'whole-batch groceries generated once');
select ok(exists(select 1 from public.meals where owner_user_id=auth.uid() and app_id like 'group-copy-%'),'personal immutable recipe retained');
select throws_ok($$update public.meals set notes='changed' where owner_user_id=auth.uid() and app_id like 'group-copy-%'$$,'42501',null,'direct recipe write remains denied');
select lives_ok($$select public.copy_cooking_recipe('{"recipeId":"meal-korean-beef-bowl","idempotencyKey":"personal-copy"}')$$,'member may save editable personal copy');
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','propose-week','day',6,'groupRevision',(public.get_cooking_group_week('2026-10-18')->'group'->>'revision')::integer,'idempotencyKey','propose-saturday'))$$,'member proposes week start');
select is(public.get_cooking_group_week('2026-10-18')->'group'->>'weekStartsOn','0','proposal alone does not regroup');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004102';
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','vote-week','proposalId',public.get_cooking_group_week('2026-10-18')->'group'->'proposal'->>'id','approve',true,'groupRevision',(public.get_cooking_group_week('2026-10-18')->'group'->>'revision')::integer,'idempotencyKey','approve-saturday'))$$,'unanimous approval regroups atomically');
select is(public.get_cooking_group_week('2026-10-17')->'group'->>'weekStartsOn','6','both accounts follow confirmed preference');
select is(jsonb_array_length(public.get_cooking_group_week('2026-10-17')->'assignments'),2,'assignment dates survive regrouping');
select is((public.get_cooking_group_week('2026-10-17')->'grocery'->>'totalAmountCentavos')::numeric,120550::numeric,'shared spending carries once');
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','propose-week','day',0,'groupRevision',(public.get_cooking_group_week('2026-10-17')->'group'->>'revision')::integer,'idempotencyKey','propose-sunday'))$$,'reverse transition can be proposed');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004101';
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','vote-week','proposalId',public.get_cooking_group_week('2026-10-17')->'group'->'proposal'->>'id','approve',true,'groupRevision',(public.get_cooking_group_week('2026-10-17')->'group'->>'revision')::integer,'idempotencyKey','approve-sunday'))$$,'reverse transition applies after unanimous approval');
select is(jsonb_array_length(public.get_cooking_group_week('2026-10-18')->'assignments'),2,'reverse transition preserves assignments');
select is((select sum((grocery->>'totalAmountCentavos')::numeric) from public.cooking_group_weeks),120550::numeric,'reverse transition never duplicates shared spending');
select is((select count(*) from public.cooking_group_weeks where grocery->>'totalAmountCentavos' is not null),1::bigint,'amount moves to exactly one destination');
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','propose-week','day',6,'groupRevision',(public.get_cooking_group_week('2026-10-18')->'group'->>'revision')::integer,'idempotencyKey','propose-saturday-again'))$$,'repeated boundary change can be proposed');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004102';
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','vote-week','proposalId',public.get_cooking_group_week('2026-10-18')->'group'->'proposal'->>'id','approve',true,'groupRevision',(public.get_cooking_group_week('2026-10-18')->'group'->>'revision')::integer,'idempotencyKey','approve-saturday-again'))$$,'repeated transition applies atomically');
select is((select sum((grocery->>'totalAmountCentavos')::numeric) from public.cooking_group_weeks),120550::numeric,'reused weeks cannot resurrect stale spending');
select is((select count(*) from public.cooking_calendar_transitions),3::bigint,'every shared transition remains auditable');
select ok(not exists(select 1 from jsonb_array_elements(public.get_cooking_group_week('2026-10-17')->'assignments') a where a->>'date'<>'2026-10-18'),'actual meal dates never move during regrouping');
reset role;
insert into group_test_state values('protected-assignment',(select jsonb_build_object('id',id,'memberId',user_id,'date',meal_date,'slot',meal_slot,'name','Saved basis') from public.cooking_assignments where user_id='00000000-0000-0000-0000-000000004101' limit 1));
insert into public.nutrition_logs(app_id,user_id,log_date,meal_slot,custom_name,servings,serving_quantity,calories,protein_g,carbs_g,fat_g,estimated,confidence,source,value_source,planned_meal_app_id)
values('corrected-linked-history','00000000-0000-0000-0000-000000004101','2026-10-19','snack','Corrected actual',1,1,100,10,10,2,true,'medium','User provided','user_provided',(select value->>'id' from group_test_state where name='protected-assignment'));
set local role service_role;
set local "request.jwt.claim.role"='service_role';
update group_test_state set value=value||'{"weekOf":"2026-10-17","mode":"replace"}'::jsonb where name='input';
insert into group_test_state values('protected-context',public.get_group_planning_context('00000000-0000-0000-0000-000000004101',(select value from group_test_state where name='input')));
select is((select a->>'protected' from jsonb_array_elements((select value->'members' from group_test_state where name='protected-context')) m cross join lateral jsonb_array_elements(m->'occupied') a where m->>'id'='00000000-0000-0000-0000-000000004101' and a->>'id'=(select value->>'id' from group_test_state where name='protected-assignment')),'true','linked history remains protected after its actual date and slot change');
insert into group_test_state values('protected-preview',public.store_group_planning_preview('00000000-0000-0000-0000-000000004101',(select value from group_test_state where name='input'),jsonb_build_object('basis',(select value->>'basis' from group_test_state where name='protected-context'),'warnings','[]'::jsonb,'batches','[]'::jsonb,'replacements',jsonb_build_array((select value from group_test_state where name='protected-assignment')),'assignments',jsonb_build_array(jsonb_build_object('id','protected-replacement','memberId','00000000-0000-0000-0000-000000004102','recipeId','meal-korean-beef-bowl','date','2026-10-18','slot','dinner','servings',1)))));
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000004101';
select throws_ok($$select public.commit_cooking_group_plan(jsonb_build_object('previewId',(select value->>'id' from group_test_state where name='protected-preview'),'acknowledged',true,'idempotencyKey','protected-replacement-commit'))$$,'P0001',null,'commit rejects replacement of a moved linked log basis');
select is((select count(*) from public.cooking_generations),1::bigint,'failed protected replacement creates no generation');
select is((select log_date::text||':'||meal_slot from public.nutrition_logs where app_id='corrected-linked-history'),'2026-10-19:snack','failed replacement never changes actual history');
select lives_ok($$select public.cooking_group_command(jsonb_build_object('action','leave','groupId',(select value->'group'->>'id' from group_test_state where name='invite'),'groupRevision',(public.get_cooking_group_week('2026-10-17')->'group'->>'revision')::integer,'idempotencyKey','leave-group'))$$,'member may leave');
select is(public.get_cooking_group_week('2026-10-17')->'group','null'::jsonb,'leaving revokes group access');
select is((select count(*) from public.cooking_group_weeks),0::bigint,'former member cannot read shared groceries');
select * from finish();
rollback;
